// 1. Cargar librerías del ecosistema
await game.snippet("ambientes");
const P = await game.snippet("particulas-voxel");

// 2. Estado de la escena
let estadoNoche = false;
let estadoNiebla = false;
let estadoHerramienta = false; // Sin herramienta en mano para estética limpia

// Configuración inicial
game.glowLevel = 15;
game.glowFocus = 0.2;
game.showTool(estadoHerramienta);

// Atmósferas calibradas para el Santuario
const ATMOSFERA = {
  ATARDECER: {
    cielo: {
      horizonte: [1.00, 0.65, 0.25],
      medio:     [0.92, 0.35, 0.45],
      cenit:     [0.28, 0.15, 0.45],
      suelo:     [0.35, 0.20, 0.15]
    },
    niebla: { near: 50, far: 380, tinte: 0.05 },
    luz: 0.85,
    sombra: 0.55
  },
  NOCHE_LUMINOSA: {
    cielo: {
      horizonte: [0.16, 0.20, 0.38],
      medio:     [0.09, 0.12, 0.24],
      cenit:     [0.04, 0.06, 0.14],
      suelo:     [0.06, 0.08, 0.14]
    },
    niebla: { near: 40, far: 240, tinte: 0.08 },
    luz: 0.55,
    sombra: 0.65
  }
};

function aplicarAtmosfera(cfg, seg = 1.5) {
  game.cielo(cfg.cielo);
  game.niebla(cfg.niebla);
  game.luz(cfg.luz);
  game.sunShade = cfg.sombra;
}

aplicarAtmosfera(ATMOSFERA.ATARDECER, 0);
game.reflejoEntorno = true;
game.reflejoOndas = true;
game.reflejoPlanoY = 10.0;

