game.osd.alPulsar('TOGGLE_NIEBLA', () => {
  estadoNiebla = !estadoNiebla;
  refrescarEntorno();
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

game.osd.alPulsar('REFLEJOS', () => {
  game.reflejoEntorno = !game.reflejoEntorno;
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
