  game.osd.abrir('menu_santuario');
});

// 7. Autoarranque en modo CÁMARA ORBITAL DIRECTA
iniciarCamaraOrbital();

toast('🏯 Santuario Zen HD listo · Gran Bosque de Sakura Milenario · O menú', 7);
